"use strict";
/* ---- chatkb/kb_bio.js ---- */
/* ============ CHAT BASE: biohacking, sleep, cycle, wellbeing (evidence-based, no miracle claims) ============ */
kbAdd('bio',[
 ['biohack','биохак|биохакинг|продлить молодость|долголети|антиэйдж|biohack|longevity|anti-?aging',
  ['Самый доказанный биохакинг скучный, но работает: сон 7–9 часов, силовые 2–3 раза в неделю, 8–10 тысяч шагов, белок, овощи, свет утром и близкие люди.','Прежде чем покупать добавки и гаджеты, проверь базу: сон, движение, питание, стресс. Это 90% результата.','Из доказанного для долголетия: сила хвата и мышцы ног, кардио-выносливость (зона 2), социальные связи, отказ от курения, умеренный алкоголь или его отсутствие.','В разделе «Биохакинг» практики отмечены звёздами по силе доказательств — начни с тех, где их больше.'],
  ['The most proven biohacks are boring but work: 7–9 h sleep, strength training, 8–10k steps, protein, veg, morning light, close people.','Before buying supplements and gadgets, check the basics: sleep, movement, food, stress.']],
 ['sleep','сон|спать|высыпа|бессонниц|уснуть|заснуть|засыпа|просыпаюсь ночью|режим сна|sleep|insomnia|can.?t fall asleep|wake up at night',
  ['Сон — главный биохак. 7–9 часов в одно и то же время, даже в выходные. Это влияет на аппетит, настроение и прогресс.','Гигиена сна: прохладная тёмная спальня (18–20°), без экранов за час до сна, без кофе после 14–15, ужин за 2–3 часа.','Утренний свет 10–15 минут на улице помогает вечером легче уснуть: это настраивает внутренние часы.','Если не можешь уснуть 20 минут — встань, займись спокойным делом при тусклом свете, вернись, когда захочется спать.','Бессонница дольше месяца — повод к врачу. Хорошо работает КПТ-И (когнитивно-поведенческая терапия бессонницы), лучше снотворных.','Недосып повышает голод и тягу к сладкому на следующий день. Так что сон — это ещё и про фигуру.'],
  ['Sleep is the top biohack: 7–9 hours at the same time, even on weekends.','Sleep hygiene: a cool dark room, no screens an hour before bed, no coffee after 2–3 pm.','10–15 minutes of morning daylight helps you fall asleep in the evening.','Insomnia longer than a month — see a doctor. CBT-I works better than sleeping pills.']],
 ['nap','дневной сон|поспать днем|поспать днём|nap',
  ['Дневной сон — 15–25 минут до 15 часов. Дольше — проснёшься разбитой и хуже уснёшь ночью.','Кофе-сон: выпей кофе и сразу ляг на 20 минут. Кофеин подействует как раз к пробуждению.'],
  ['Naps: 15–25 minutes before 3 pm. Longer leaves you groggy.']],
 ['melatonin','мелатонин|снотворн|melatonin|sleeping pill',
  ['Мелатонин помогает при смене часовых поясов и сбитом режиме, в малых дозах (0,5–1 мг) за 1–2 часа до сна. Долго принимать — лучше обсудить с врачом.','Снотворные — только по назначению врача. Сначала стоит наладить режим и гигиену сна.'],
  ['Melatonin helps with jet lag in small doses (0.5–1 mg). For long use, ask a doctor.']],
 ['cold','холодн(ый|ая) душ|закалива|моржев|ледян|криотерап|cold shower|cold plunge|ice bath',
  ['Холодный душ бодрит и улучшает настроение, но жир не «сжигает» заметно. Начни с 15–30 секунд прохладной воды в конце обычного душа.','Ледяные ванны сразу после силовой могут слегка мешать росту мышц. Если цель — мышцы, делай их в другое время.','При проблемах с сердцем и давлением резкий холод — только после разговора с врачом.'],
  ['Cold showers boost mood and alertness, but don’t burn much fat. Start with 15–30 seconds at the end.','With heart or blood pressure problems, check with a doctor before cold exposure.']],
 ['sauna','баня|сауна|парилк|sauna|steam',
  ['Сауна 2–4 раза в неделю связана с пользой для сердца и расслаблением. Пей воду, не ходи пьяной и после тяжёлой тренировки — не сразу.','Вес после бани — это вода, он вернётся после стакана воды. Не способ похудеть.','При беременности, высоком давлении и болезнях сердца сауну сначала обсуди с врачом.'],
  ['Sauna 2–4 times a week is linked to heart benefits and relaxation. Drink water, never go drunk.','Weight lost in a sauna is water.']],
 ['breathwork','дыхательн|дыхание по|вим хоф|пранаям|breathwork|wim hof|pranayama',
  ['Длинный выдох (вдох 4 — выдох 6) успокаивает нервную систему за пару минут. Это самая простая доказанная практика.','«Физиологический вздох»: два вдоха носом подряд и длинный выдох ртом. 1–3 раза — и тревога снижается.','Гипервентиляционные практики (Вим Хоф) нельзя делать в воде, за рулём и при эпилепсии, беременности, проблемах с сердцем.'],
  ['A long exhale (in 4, out 6) calms your nervous system in minutes.','Physiological sigh: two inhales through the nose and a long exhale.']],
 ['steps','10000 шагов|10 000 шагов|сколько шагов|шагомер|steps a day|step count',
  ['Твоя цель — {steps} шагов. Исследования показывают пользу уже с 6–8 тысяч, а дальше эффект растёт медленнее.','Шаги — лучший способ добавить расход без роста аппетита. Прогулка после еды ещё и выравнивает сахар в крови.'],
  ['Your goal is {steps} steps. Benefits start at 6–8 thousand.','A walk after meals also smooths blood sugar.']],
 ['sugarspike','сахар в крови|инсулин|резистентност|глюкоз|скачки сахара|blood sugar|insulin|glucose spike',
  ['Сгладить скачки сахара помогают: овощи и белок в начале еды, прогулка 10 минут после еды, цельные крупы вместо белого хлеба.','Если часто клонит в сон после еды, сильная тяга к сладкому, тёмные пятна на коже шеи — стоит сдать глюкозу и инсулин натощак и показаться эндокринологу.'],
  ['To smooth blood sugar: veg and protein first, a 10-minute walk after meals, whole grains.']],
 ['fasting','интервальное голодание|16:8|16/8|окно питания|intermittent fasting|eating window',
  ['Интервальное голодание 16:8 — просто способ есть в окне. Работает за счёт меньших калорий, а не магии. Если тебе так удобно — можно, если нет — не обязательно.','Девушкам с нерегулярным циклом, пищевыми расстройствами, при беременности и кормлении голодание не подходит.','Мягкий вариант: 12 часов ночной паузы (например, с 20:00 до 8:00). Это полезно почти всем.'],
  ['16:8 fasting works through fewer calories, not magic. Fine if it suits you.','Not for irregular cycles, eating disorders, pregnancy or breastfeeding.']],
 ['supplementsbio','креатин|коллаген|омега|магний|ашваганд|куркум|креатин|creatine|collagen|magnesium|ashwagandha|turmeric',
  ['Креатин (3–5 г в день) — одна из самых изученных добавок: сила, мышцы, возможно память. Безопасен для здоровых людей, вес может вырасти на 1 кг за счёт воды в мышцах.','Коллаген: есть исследования о пользе для кожи и суставов, но эффект умеренный. Обычного белка в еде при этом тоже должно хватать.','Омега-3 полезна, если редко ешь жирную рыбу. Магний — при судорогах, ПМС и плохом сне.','Ашваганда может немного снижать стресс, но есть противопоказания (щитовидка, беременность, печень). Лучше обсудить с врачом.','Добавки не заменят сон, движение и еду. Покупай только то, где доказана польза и есть причина.'],
  ['Creatine (3–5 g/day) is one of the best-studied supplements: strength, muscle, maybe memory.','Supplements don’t replace sleep, movement and food.']],
 ['skin','кож[аиу]|прыщ|акне|морщин|целлюлит|растяжк(и|ами) на коже|пигмент|skin|acne|pimple|wrinkle|cellulite|stretch marks',
  ['Для кожи главное: SPF каждый день, сон, вода, овощи и белок. Солнцезащита — лучший доказанный антиэйдж.','Целлюлит есть у 80–90% женщин — это особенность строения кожи, а не болезнь. Силовые и снижение жира делают его менее заметным.','Акне — к дерматологу: сейчас есть эффективное лечение. Иногда связано с гормонами — проверим с гинекологом-эндокринологом.','Растяжки (стрии) бывают при быстром изменении веса. Со временем светлеют. Медленный темп похудения и набора помогает избежать новых.'],
  ['For skin: daily SPF, sleep, water, veg and protein. Sunscreen is the best anti-aging.','Cellulite affects 80–90% of women; it’s normal, not a disease.','For acne see a dermatologist, there are good treatments.']],
 ['cycle','цикл|овуляц|фолликул|лютеин|фаза цикла|cycle|ovulat|follicular|luteal',
  ['По фазам цикла: в фолликулярной (после месячных) сил больше — можно тренироваться интенсивнее. В лютеиновой (перед месячными) — больше отдыха и мягче к себе.','Программа учитывает цикл: в мягкие дни ставит лёгкие тренировки, а в сильные — предлагает чуть больше нагрузки.','В лютеиновой фазе расход энергии немного выше — нормально хотеть есть чуть больше. Добавь сытной еды, а не терпи.','Отмечай начало месячных в разделе «Цикл» — так прогноз фаз будет точнее.'],
  ['In the follicular phase (after your period) you have more energy; in the luteal phase be gentler with yourself.','The program adapts to your cycle: soft days get gentle workouts.']],
 ['pms','пмс|перед месячными|ПМС|раздражительн(ая|ость) перед|pms|before my period',
  ['При ПМС помогают: регулярное движение, магний, сон, меньше соли, кофе и алкоголя, сложные углеводы. И разрешение себе быть не в ресурсе.','Отёки и +1–2 кг перед месячными — это вода, а не жир. Через пару дней после начала уйдёт.','Если ПМС очень тяжёлый (сильная депрессия, злость, мешает жить) — возможно, это ПМДР. Это лечится, обратись к гинекологу.'],
  ['For PMS: regular movement, magnesium, sleep, less salt, coffee and alcohol.','+1–2 kg before your period is water, not fat.']],
 ['periodpain','болит живот (при|во время) месячн|месячные болят|болят месячные|больно (на|при|во время) месячн|болезненные месячные|спазмы|менструальн(ая|ые) бол|cramps|period pain',
  ['При болях в первые дни: грелка на живот, мягкая растяжка (поза ребёнка, кошка), прогулка, тёплый чай. Обезболивающее по инструкции — это нормально.','Если боль такая, что не можешь встать, или не помогают обезболивающие — проверься у гинеколога (например, на эндометриоз).'],
  ['For cramps: a heat pad, gentle stretches, a walk, warm tea. Pain relief per instructions is fine.','If pain is disabling or painkillers don’t help, see a gynaecologist.']],
 ['irregular','нет месячных|задержк|пропали месячные|нерегулярн(ый|ые)|сбился цикл|no period|missed period|irregular period|amenorr',
  ['Если пропали месячные (и ты не беременна) — частые причины: слишком мало еды, много тренировок, стресс, резкое похудение. Это сигнал тела, что ресурсов мало. Важно сходить к гинекологу.','Пропавший цикл на фоне диеты опасен для костей и гормонов. Тут нужно есть больше, а не меньше 💛','Задержка больше 7 дней — сделай тест на беременность, а дальше к врачу.'],
  ['If your period stops (and you’re not pregnant), common reasons are too little food, too much training, stress. See a gynaecologist.','A lost cycle during dieting harms bones and hormones. Eat more, not less 💛'],{pri:3}],
 ['menopause','климакс|менопауз|приливы|перименопауз|menopause|hot flash|perimenopause',
  ['В менопаузу особенно важны силовые (кости и мышцы), белок, кальций и витамин D. Приливы облегчают прохладная спальня, меньше алкоголя и острого.','Если приливы и бессонница сильно мешают — поговори с гинекологом: сейчас есть безопасные варианты лечения.'],
  ['In menopause strength training, protein, calcium and vitamin D matter most.','If hot flushes and insomnia are severe, talk to a gynaecologist.']],
 ['thyroid','щитовидк|ттг|гипотиреоз|тиреоид|thyroid|tsh|hypothyroid',
  ['При гипотиреозе худеть можно, но при подобранной дозе гормонов. Если вес стоит, усталость, холодно, выпадают волосы — сдай ТТГ.','Тренироваться с заболеванием щитовидки можно и полезно, если состояние компенсировано. Таблетку пей натощак, за 30–60 минут до еды и кофе.'],
  ['With hypothyroidism you can lose weight once your dose is right. Check TSH if tired, cold, losing hair.']],
 ['tests','какие анализы|что сдать|чекап|обследован|анализы сдать|check-?up|blood test|which tests',
  ['Базовый чекап раз в год: общий анализ крови, ферритин, глюкоза, ТТГ, витамин D, липидный профиль, а также гинеколог и стоматолог.','При усталости и выпадении волос: ферритин, ТТГ, витамин D, B12, общий анализ крови.','Анализы лучше сдавать натощак утром, а гормоны — в определённые дни цикла (уточни у врача).'],
  ['Yearly check-up: blood count, ferritin, glucose, TSH, vitamin D, lipids, plus gynaecologist and dentist.']],
 ['energy','энергии нет|нет энергии|вялость|бодрост|как взбодриться|постоянно хочу спать|no energy|sluggish|boost energy|always sleepy',
  ['Для бодрости: свет утром, стакан воды, движение 10 минут, завтрак с белком. Кофе — через 1–1,5 часа после пробуждения.','Постоянная вялость — проверь сон, железо (ферритин), витамин D, щитовидку. Это частые причины у девушек.','Мини-перезагрузка днём: 5 минут на улице, 10 приседаний, умыться холодной водой.'],
  ['For energy: morning light, water, 10 minutes of movement, a protein breakfast.','Constant fatigue — check sleep, iron, vitamin D and thyroid.']],
 ['screen','сижу в телефоне|залипаю в телефон|в телефоне|соцсет|инстаграм|тикток|экранное время|залипаю|phone|social media|instagram|tiktok|screen time',
  ['Соцсети могут сильно влиять на настроение и самооценку. Поставь лимит времени и убери телефон из спальни.','Первый час после пробуждения без телефона — маленькая привычка, которая сильно меняет день.','Отпишись от аккаунтов, после которых чувствуешь себя хуже. Твоя лента — твоё пространство.'],
  ['Social media affects mood and self-esteem. Set a time limit and keep the phone out of the bedroom.','Unfollow accounts that make you feel worse.']],
 ['sun','витамин д|солнц|загар|spf|солярий|vitamin d|sunscreen|tanning|solarium',
  ['Витамин D зимой часто низкий. Сдай анализ и подбери дозу с врачом. Летом 10–20 минут солнца на руки и ноги — но без ожогов.','SPF 30–50 каждый день на лицо — лучшая защита от старения кожи. Солярий повышает риск меланомы, лучше без него.'],
  ['Vitamin D is often low in winter. Test and dose with a doctor.','Daily SPF 30–50 is the best anti-aging; skip tanning beds.']],
 ['habits','привычк|как внедрить|новая привычка|режим дня|habit|routine',
  ['Новая привычка приживается легче, если привязать её к старой: «после того как почищу зубы — 10 приседаний».','Делай привычку смешно маленькой сначала: 1 стакан воды, 2 минуты растяжки. Потом увеличишь.','Отслеживай привычки галочками: цепочка выполненных дней мотивирует не прерывать её.','Внедряй по одной привычке в 2–3 недели, а не всё сразу с понедельника.'],
  ['Attach a new habit to an old one: “after brushing my teeth — 10 squats”.','Start tiny, then grow. One habit every 2–3 weeks.']],
 ['smoking','курю|курить|бросить курить|вейп|сигарет|smok|vape|quit smoking',
  ['Бросить курить — лучшее, что можно сделать для здоровья. Помогает: никотинозаместительная терапия, поддержка, замена ритуала (прогулка, вода, жвачка).','Набор 2–3 кг после отказа от курения бывает, но польза для сердца и лёгких несравнимо больше. Движение и белок помогают.','Вейп тоже вреден: никотин и раздражение лёгких. Поддержку можно получить у врача-нарколога или терапевта.'],
  ['Quitting smoking is the best thing for your health. Nicotine replacement and support help.'],{adult:1}],
 ['posturebio','сижу весь день|сидячая работ|за компьютером|шея болит|болит шея|desk job|sitting all day|neck pain',
  ['При сидячей работе — вставай каждые 30–60 минут хотя бы на минуту. В разделе «Осанка» есть 5-минутки и напоминания.','Шея болит от телефона и ноутбука: подними экран на уровень глаз, а голову держи «на макушке». Растяжка шеи 2–3 раза в день.'],
  ['With a desk job, stand up every 30–60 minutes. Posture has 5-minute routines and reminders.','Raise your screen to eye level to spare your neck.']]
]);

